import { useParams, useNavigate } from "react-router-dom";
import {
  ArrowLeft, MapPin, Phone, User, Calendar,
  Eye, ClipboardList, AlertCircle, Hash, Sparkles,
  TrendingUp, ChevronRight, Zap,
} from "lucide-react";
import {
  Card, PageHeader, Button, ScoreRing, GradeBadge, EmptyState,
  MiniSparkline, CountUp, Breadcrumb, Badge,
} from "@/components/ui";
import { useStoreById, useInspectionsByStore, useStoreScore } from "@/lib/data";
import { cn } from "@/lib/utils";

export default function StoreDetail() {
  const { id } = useParams();
  const navigate = useNavigate();

  const store = useStoreById(id || "");
  const inspections = useInspectionsByStore(store?.id || "");
  // 评分从巡检记录派生，新门店无巡检时返回 null
  const derivedScore = useStoreScore(store?.id || "");

  // 记录不存在
  if (!store) {
    return (
      <div className="animate-fade-in flex flex-col items-center justify-center min-h-[50vh] text-center">
        <div className="w-16 h-16 rounded-2xl bg-ink-100 flex items-center justify-center mb-4">
          <AlertCircle className="w-8 h-8 text-ink-400" />
        </div>
        <h2 className="text-xl font-bold text-ink-800 mb-2">门店不存在</h2>
        <p className="text-sm text-ink-500 mb-6">该门店 ID 可能已被删除或地址输入有误</p>
        <Button variant="gradient" onClick={() => navigate("/store")}>
          <ArrowLeft className="w-4 h-4" /> 返回门店列表
        </Button>
      </div>
    );
  }

  // 统计
  const totalIns = inspections.length;
  const totalRisks = inspections.reduce((s, i) => s + i.riskCount, 0);
  const avgScore = derivedScore;
  const hasScore = avgScore !== null;
  const grade: "优" | "良" | "中" | "差" =
    avgScore !== null && avgScore >= 90 ? "优" :
    avgScore !== null && avgScore >= 75 ? "良" :
    avgScore !== null && avgScore >= 60 ? "中" : "差";

  // 趋势线
  const trendData = inspections.length > 0
    ? [...inspections].sort((a, b) => a.inspectTime.localeCompare(b.inspectTime)).map((i) => i.score)
    : [60, 65, 70, 68, 75, 80, 82, avgScore ?? 0];

  const isNewStore = store.id.startsWith("store-new-");

  return (
    <div className="animate-fade-in">
      <div className="mb-4">
        <Breadcrumb
          items={[
            { label: "门店管理", onClick: () => navigate("/store") },
            { label: store.name },
          ]}
        />
      </div>
      <PageHeader
        title={store.name}
        subtitle="门店详情 · 食安巡检档案"
        badge={
          <div className="flex items-center gap-2">
            {isNewStore && <Badge variant="success" size="sm">NEW</Badge>}
            <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-emerald-50 text-emerald-700 text-[10px] font-semibold tracking-wider border border-emerald-200/80">
              <Sparkles className="w-3 h-3" /> {store.code}
            </span>
          </div>
        }
        actions={
          <>
            <Button
              variant="gradient"
              size="md"
              onClick={() => navigate(`/inspection/new?storeId=${store.id}`)}
              icon={<Zap className="w-4 h-4" />}
            >
              发起巡检
            </Button>
            <Button
              variant="secondary"
              size="md"
              onClick={() => navigate("/store")}
              icon={<ArrowLeft className="w-4 h-4" />}
            >
              返回列表
            </Button>
          </>
        }
      />

      {/* Hero 卡片 */}
      <div className="relative rounded-2xl bg-gradient-to-r from-brand-950 via-brand-900 to-ink-900 p-6 text-white overflow-hidden mb-6">
        <div className="absolute -top-20 -right-10 w-72 h-72 rounded-full bg-cyan-500/20 blur-3xl pointer-events-none" />
        <div className="absolute -bottom-16 -left-10 w-64 h-64 rounded-full bg-violet-500/15 blur-2xl pointer-events-none" />

        <div className="relative grid grid-cols-[1fr_auto] gap-8 items-center">
          <div>
            <div className="flex items-center gap-2 mb-3 flex-wrap">
              <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[10px] font-semibold tracking-wider bg-emerald-500/20 border border-emerald-400/40 text-emerald-200">
                <span className="w-1.5 h-1.5 rounded-full bg-emerald-400 shadow-[0_0_6px_rgba(16,185,129,0.6)]" />
                ACTIVE
              </span>
              <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[10px] font-semibold tracking-wider bg-white/10 border border-white/20 text-white/80">
                <MapPin className="w-3 h-3" /> {store.region}
              </span>
            </div>
            <h1 className="text-3xl font-bold font-display tracking-tight mb-2">
              {store.name}
            </h1>
            <p className="text-sm text-white/70 flex items-center gap-1.5">
              <MapPin className="w-3.5 h-3.5" />
              {store.address}
            </p>
          </div>

          <div className="flex flex-col items-center">
            {hasScore ? (
              <>
                <ScoreRing score={avgScore} size={140} />
                <div className="mt-2">
                  <GradeBadge grade={grade} large />
                </div>
              </>
            ) : (
              <div className="flex flex-col items-center justify-center w-[140px] h-[140px] rounded-full border-4 border-white/20 text-white/60">
                <span className="text-xs">暂无评分</span>
                <span className="text-[10px] mt-1">完成巡检后生成</span>
              </div>
            )}
          </div>
        </div>

        {/* Hero 统计 */}
        <div className="relative grid grid-cols-3 gap-4 mt-6 pt-6 border-t border-white/15">
          <div className="flex items-center gap-3">
            <div className="w-9 h-9 rounded-lg bg-white/10 backdrop-blur border border-white/20 flex items-center justify-center">
              <ClipboardList className="w-4 h-4 text-white" />
            </div>
            <div>
              <p className="text-[10px] text-white/60 font-semibold tracking-widest uppercase">巡检次数</p>
              <p className="text-2xl font-bold font-display tracking-tight tabular-nums">
                <CountUp end={totalIns} duration={1200} suffix=" 次" />
              </p>
            </div>
          </div>
          <div className="flex items-center gap-3">
            <div className="w-9 h-9 rounded-lg bg-white/10 backdrop-blur border border-white/20 flex items-center justify-center">
              <AlertCircle className="w-4 h-4 text-white" />
            </div>
            <div>
              <p className="text-[10px] text-white/60 font-semibold tracking-widest uppercase">风险项</p>
              <p className="text-2xl font-bold font-display tracking-tight tabular-nums">
                <CountUp end={totalRisks} duration={1200} suffix=" 项" />
              </p>
            </div>
          </div>
          <div className="flex items-center gap-3">
            <div className="w-9 h-9 rounded-lg bg-white/10 backdrop-blur border border-white/20 flex items-center justify-center">
              <TrendingUp className="w-4 h-4 text-white" />
            </div>
            <div className="flex-1 min-w-0">
              <p className="text-[10px] text-white/60 font-semibold tracking-widest uppercase mb-1">分数趋势</p>
              <MiniSparkline
                data={trendData}
                color="#06b6d4"
                width={140}
                height={32}
              />
            </div>
          </div>
        </div>
      </div>

      {/* 基础信息 - 2x3 网格 */}
      <div className="mb-4 flex items-end justify-between">
        <div>
          <p className="text-[10px] text-ink-400 font-semibold tracking-widest uppercase">Store Info</p>
          <h3 className="text-base font-bold font-display tracking-tight text-ink-900 mt-0.5">
            基础信息
          </h3>
        </div>
        {totalRisks > 0 && (
          <Button
            variant="ghost"
            size="sm"
            onClick={() => navigate("/risk")}
            icon={<AlertCircle className="w-3.5 h-3.5" />}
          >
            查看风险详情
            <ChevronRight className="w-3 h-3" />
          </Button>
        )}
      </div>

      <div className="grid grid-cols-3 gap-3 mb-6">
        <InfoItem icon={Hash} label="门店编号" value={store.code} mono />
        <InfoItem icon={MapPin} label="所在区域" value={store.region} />
        <InfoItem icon={User} label="店长" value={store.manager} />
        <InfoItem icon={Phone} label="联系电话" value={store.phone} mono />
        <InfoItem icon={Calendar} label="开业日期" value={store.openDate} />
        <InfoItem icon={MapPin} label="详细地址" value={store.address} wide />
      </div>

      {/* 巡检历史 */}
      <div className="mb-4 flex items-end justify-between">
        <div>
          <p className="text-[10px] text-ink-400 font-semibold tracking-widest uppercase">Inspection History</p>
          <h3 className="text-base font-bold font-display tracking-tight text-ink-900 mt-0.5">
            巡检历史记录
            <span className="text-ink-400 text-sm font-normal ml-2">共 {inspections.length} 次</span>
          </h3>
        </div>
      </div>

      <Card className="overflow-hidden">
        {inspections.length === 0 ? (
          <EmptyState
            icon={<ClipboardList className="w-12 h-12" />}
            text="暂无巡检记录"
          />
        ) : (
          <table className="w-full text-sm">
            <thead>
              <tr className="bg-gradient-to-r from-ink-50 to-ink-100/50 text-ink-500 text-xs">
                <th className="text-left px-5 py-3.5 font-semibold tracking-wider uppercase text-[10px]">巡检时间</th>
                <th className="text-left px-5 py-3.5 font-semibold tracking-wider uppercase text-[10px]">使用模板</th>
                <th className="text-left px-5 py-3.5 font-semibold tracking-wider uppercase text-[10px]">巡检员</th>
                <th className="text-center px-5 py-3.5 font-semibold tracking-wider uppercase text-[10px]">得分</th>
                <th className="text-center px-5 py-3.5 font-semibold tracking-wider uppercase text-[10px]">评级</th>
                <th className="text-center px-5 py-3.5 font-semibold tracking-wider uppercase text-[10px]">高</th>
                <th className="text-center px-5 py-3.5 font-semibold tracking-wider uppercase text-[10px]">中</th>
                <th className="text-center px-5 py-3.5 font-semibold tracking-wider uppercase text-[10px]">低</th>
                <th className="text-right px-5 py-3.5 font-semibold tracking-wider uppercase text-[10px]">操作</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-ink-100/80">
              {inspections.map((ins) => (
                <tr
                  key={ins.id}
                  className="group hover:bg-gradient-to-r hover:from-brand-50/40 hover:to-transparent cursor-pointer transition"
                  onClick={() => navigate(`/inspection/${ins.id}`)}
                >
                  <td className="px-5 py-3.5 text-ink-600 text-xs font-mono tabular-nums">
                    {ins.inspectTime}
                  </td>
                  <td className="px-5 py-3.5">
                    <span className="px-2 py-0.5 text-[11px] rounded-md bg-ink-100/60 text-ink-600 font-medium">
                      {ins.templateName}
                    </span>
                  </td>
                  <td className="px-5 py-3.5">
                    <div className="flex items-center gap-1.5">
                      <div className="w-5 h-5 rounded-full bg-gradient-to-br from-cyan-500 to-brand-700 text-white text-[10px] font-semibold flex items-center justify-center">
                        {ins.inspector[0]}
                      </div>
                      <span className="text-ink-600 text-xs">{ins.inspector}</span>
                    </div>
                  </td>
                  <td className="px-5 py-3.5 text-center">
                    <span className={cn(
                      "font-bold font-display tabular-nums",
                      ins.score >= 90 ? "text-emerald-600" :
                      ins.score >= 75 ? "text-brand-700" :
                      ins.score >= 60 ? "text-amber-600" : "text-red-500"
                    )}>
                      {ins.score}
                    </span>
                  </td>
                  <td className="px-5 py-3.5 text-center">
                    <GradeBadge grade={ins.grade} />
                  </td>
                  <td className="px-5 py-3.5 text-center">
                    {ins.highRiskCount > 0 ? (
                      <span className="inline-flex items-center gap-1">
                        <span className="w-1.5 h-1.5 rounded-full bg-red-500" />
                        <span className="text-xs font-semibold text-red-600 tabular-nums">{ins.highRiskCount}</span>
                      </span>
                    ) : (
                      <span className="text-ink-300">—</span>
                    )}
                  </td>
                  <td className="px-5 py-3.5 text-center">
                    {ins.midRiskCount > 0 ? (
                      <span className="inline-flex items-center gap-1">
                        <span className="w-1.5 h-1.5 rounded-full bg-orange-500" />
                        <span className="text-xs font-semibold text-orange-500 tabular-nums">{ins.midRiskCount}</span>
                      </span>
                    ) : (
                      <span className="text-ink-300">—</span>
                    )}
                  </td>
                  <td className="px-5 py-3.5 text-center">
                    {ins.lowRiskCount > 0 ? (
                      <span className="inline-flex items-center gap-1">
                        <span className="w-1.5 h-1.5 rounded-full bg-amber-500" />
                        <span className="text-xs font-semibold text-amber-600 tabular-nums">{ins.lowRiskCount}</span>
                      </span>
                    ) : (
                      <span className="text-ink-300">—</span>
                    )}
                  </td>
                  <td className="px-5 py-3.5 text-right">
                    <button
                      className="inline-flex items-center gap-1 px-2.5 py-1 rounded-md text-xs text-brand-600 hover:bg-brand-50 transition cursor-pointer opacity-0 group-hover:opacity-100"
                      onClick={(e) => { e.stopPropagation(); navigate(`/inspection/${ins.id}`); }}
                    >
                      <Eye className="w-3.5 h-3.5" /> 详情
                      <ChevronRight className="w-3 h-3" />
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </Card>

      {/* 底部返回 */}
      <div className="flex justify-center mt-8">
        <Button
          variant="secondary"
          size="md"
          onClick={() => navigate("/store")}
          icon={<ArrowLeft className="w-4 h-4" />}
        >
          返回门店列表
        </Button>
      </div>
    </div>
  );
}

// 信息卡项
function InfoItem({
  icon: Icon, label, value, mono, wide,
}: { icon: typeof Hash; label: string; value: string; mono?: boolean; wide?: boolean }) {
  return (
    <Card className={cn("p-3.5 flex items-center gap-3", wide && "col-span-3")}>
      <div className="w-9 h-9 rounded-lg bg-gradient-to-br from-brand-50 to-cyan-50 flex items-center justify-center shrink-0">
        <Icon className="w-4 h-4 text-brand-700" />
      </div>
      <div className="min-w-0 flex-1">
        <p className="text-[10px] text-ink-400 font-semibold tracking-widest uppercase">{label}</p>
        <p className={cn("text-sm text-ink-800 mt-0.5 truncate", mono && "font-mono")}>{value}</p>
      </div>
    </Card>
  );
}
